export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface Category {
  name: string;
  base: number;
  highAdj: number;
  maxNights: number;
  minNights: number;
  maxGuests: number;
  guestFee: number;
  flatFee: number;
}

const CATEGORIES: Record<string, Category> = {
  standard: { name: "standard", base: 80, highAdj: 30, maxNights: 14, minNights: 1, maxGuests: 2, guestFee: 0, flatFee: 0 },
  suite:    { name: "suite",    base: 150, highAdj: 60, maxNights: 21, minNights: 1, maxGuests: 4, guestFee: 25, flatFee: 0 },
  villa:    { name: "villa",    base: 300, highAdj: 120, maxNights: 28, minNights: 3, maxGuests: 8, guestFee: 0, flatFee: 500 },
};

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const cat = CATEGORIES[req.category as string];
  if (!cat) {
    return { ok: false, error: "unknown category" };
  }

  const nights = req.nights as number;
  if (!Number.isInteger(req.nights) || nights < 1 || nights > cat.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (nights < cat.minNights) {
    return { ok: false, error: "villa minimum stay" };
  }
  const guests = req.guests as number;
  if (!Number.isInteger(req.guests) || guests < 1 || guests > cat.maxGuests) {
    return { ok: false, error: "bad guests" };
  }
  if (req.season !== "low" && req.season !== "high") {
    return { ok: false, error: "bad season" };
  }

  const loyalty = req.loyaltyYears as number;
  const vip = req.coupon === "VIP";

  let total = cat.base * nights + (req.season === "high" ? cat.highAdj * nights : 0);
  if (loyalty >= 3 || vip) {
    total -= Math.floor(total / 10);
  }
  if (guests > 2) {
    total += cat.guestFee;
  }
  total += cat.flatFee;

  const policy = vip || loyalty > 2 ? "flex" : "strict";
  const line = `${cat.name}:${nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

